"""Hand-authored fictional research scenarios, not descriptions of IIT projects.

Each topic has 4 approaches x 4 settings x 4 challenges = 64 distinct scenarios.
The target metric is an intended improvement against a fictional internal control.
"""

AREAS = [
    (1, "Sustainable Energy", "Low-impact energy generation, conversion, storage and use."),
    (2, "Materials Circularity", "Recovery, reuse and redesign of materials and waste streams."),
    (3, "Green Robotics", "Resource-efficient robots and robotics for environmental applications."),
    (4, "Water for Life", "Water treatment, water monitoring and aquatic ecosystem protection."),
]


def topic(area, name, aim, approaches, contexts, challenges, skills, equipment, metric):
    return dict(
        area_id=area, name=name, aim=aim,
        approaches=approaches.split(" | "), contexts=contexts.split(" | "),
        challenges=challenges.split(" | "), skills=skills.split(" | "),
        equipment=equipment, metric=metric,
    )


